  v_spec jsonb;
  v_route record;
  v_coords jsonb;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_invalid integer;
  v_start_gap_m double precision;
  v_end_gap_m double precision;
begin
  for v_spec in select value from jsonb_array_elements(v_specs)
  loop
    v_coords := v_spec->'coords';

    select h.id,h.latitude,h.longitude,h.distance_km,t.status
      into v_route
      from public.hiking_routes h
      join public.hiking_route_tracks t on t.route_id=h.id
      where h.id=v_spec->>'id'
        and h.source='openstreetmap'
        and h.name=v_spec->>'name'
        and coalesce(h.route_ref,'')=v_spec->>'ref'
        and h.route_type='Lineal'
        and h.official_url=v_spec->>'official_url'
        and abs(h.distance_km-(v_spec->>'catalog_distance')::numeric)<0.01
        and exists (
          select 1 from public.hiking_route_regions r
          where r.route_id=h.id and r.published
        );

    if not found then
      raise exception 'DIBA route identity or published region changed: %',v_spec->>'id';
    end if;
    if v_route.status='ready' then
      continue;
    end if;
    if v_route.status<>'missing' then
      raise exception 'DIBA route status changed for %: %',v_route.id,v_route.status;
    end if;

    with points as (
      select ordinality idx,(point->>0)::double precision lat,
        (point->>1)::double precision lon
      from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
    ), steps as (
      select *,lag(lat) over(order by idx) prev_lat,
        lag(lon) over(order by idx) prev_lon
      from points
    ), distances as (
      select case when prev_lat is null then 0 else
        ST_DistanceSphere(ST_MakePoint(lon,lat),
          ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
        ST_DistanceSphere(ST_MakePoint(lon,lat),
          ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
        (lat between 27 and 45 and lon between -19 and 5) valid
      from steps
    )
    select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
      coalesce(min(center_km),999),count(*) filter(where not valid)
      into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
      from distances;

    select
      ST_DistanceSphere(
        ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
        ST_MakePoint((v_spec->'start'->>1)::double precision,(v_spec->'start'->>0)::double precision)
      ),
      ST_DistanceSphere(
        ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,(v_coords->(v_count-1)->>0)::double precision),
        ST_MakePoint((v_spec->'end'->>1)::double precision,(v_spec->'end'->>0)::double precision)
      )
      into v_start_gap_m,v_end_gap_m;

    if v_count<>(v_spec->>'point_count')::integer
      or v_invalid>0
      or abs(v_length_km-(v_spec->>'measured_km')::double precision)>0.01
      or v_max_gap_km>0.0755
      or v_center_gap_km>0.70
      or v_start_gap_m>2
      or v_end_gap_m>2 then
      raise exception 'DIBA validation failed for %: points %, length %, gap %, center %, start %, end %, invalid %',
        v_route.id,v_count,v_length_km,v_max_gap_km,v_center_gap_km,
        v_start_gap_m,v_end_gap_m,v_invalid;
    end if;

    select jsonb_agg(jsonb_build_object(
      'lat',(point->>0)::double precision,
      'lon',(point->>1)::double precision
    ) order by ordinality)
      into v_points
      from jsonb_array_elements(v_coords)
        with ordinality as p(point,ordinality);

    insert into public.hiking_route_tracks
      (route_id,status,segments,checked_at,continuity_checked,
       geometry_source,geometry_source_url,official)
    values (
      v_route.id,'ready',jsonb_build_array(v_points),now(),true,
      'Diputacio de Barcelona (Xarxa de Parcs Naturals) - GPX oficial',
      v_spec->>'gpx_url',true
    )
    on conflict(route_id) do update set
      status=excluded.status,
      segments=excluded.segments,
      checked_at=excluded.checked_at,
      continuity_checked=true,
      geometry_source=excluded.geometry_source,
      geometry_source_url=excluded.geometry_source_url,
      official=true;

    update public.hiking_routes
      set trace_available=true,
          published=true,
          distance_km=round(v_length_km::numeric,2)
      where id=v_route.id;
  end loop;
end
$curate$;
